"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_top_customers(self, limit: Any) -> Response:
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": value}
            for c, value in self._service.top_customers(limit)]})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            count, total = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            history = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "orders": [{"order_id": s.order.order_id, "status": s.order.status,
                        "total_cents": s.total_cents} for s in history],
        })

def test_unknown_customer(api):
    r = api.insights.handle_order_history("nope")
    assert r.status == 404
    assert r.body == {"error": "customer not found"}


def test_empty_history(shop):
    r = shop.insights.handle_order_history("c1")
    assert (r.status, r.body) == (200, {"customer_id": "c1", "orders": []})


def test_history_newest_first_with_discount_and_cancelled(shop):
    ids = [shop.orders.handle_create({"customer_id": "c2", "items": [{"sku": "LAMP", "quantity": 1}]}).body["order_id"]
           for _ in range(2)]
    shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 1}]})
    shop.orders.handle_cancel(ids[0])
    r = shop.insights.handle_order_history("c2")
    assert r.status == 200
    assert [o["order_id"] for o in r.body["orders"]] == [ids[1], ids[0]]
    assert [o["status"] for o in r.body["orders"]] == ["placed", "cancelled"]
    for o in r.body["orders"]:
        assert o["total_cents"] == shop.orders.handle_get(o["order_id"]).body["total_cents"]


def _order(shop, customer_id, sku, qty=1):
    return shop.orders.handle_create({"customer_id": customer_id, "items": [{"sku": sku, "quantity": qty}]}).body["order_id"]


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, "3", 1.5, None):
        r = shop.insights.handle_top_customers(bad)
        assert r.status == 400 and "error" in r.body


def test_top_customers_empty_when_no_value(shop):
    assert shop.insights.handle_top_customers(5).body == {"customers": []}


def test_top_customers_ranking_ties_zero_and_limit(shop):
    shop.customers.handle_register({"customer_id": "c0", "name": "Zed", "email": "z@example.com"})
    shop.customers.handle_register({"customer_id": "c3", "name": "Cleo", "email": "c@example.com"})
    _order(shop, "c1", "PEN")                       # 300
    _order(shop, "c0", "PEN")                       # 300 (tie with c1, c0 first)
    _order(shop, "c3", "BOOK")                      # 2500
    cancelled = _order(shop, "c2", "LAMP")          # cancelled -> value 0
    shop.orders.handle_cancel(cancelled)
    r = shop.insights.handle_top_customers(10)
    assert r.status == 200
    assert r.body["customers"] == [
        {"customer_id": "c3", "name": "Cleo", "lifetime_value_cents": 2500},
        {"customer_id": "c0", "name": "Zed", "lifetime_value_cents": 300},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 300},
    ]
    assert shop.insights.handle_top_customers(2).body["customers"] == r.body["customers"][:2]
    for entry in r.body["customers"]:
        assert entry["lifetime_value_cents"] == shop.insights.handle_lifetime_value(
            entry["customer_id"]).body["lifetime_value_cents"]


def test_lifetime_value_unknown_customer(api):
    r = api.insights.handle_lifetime_value("nope")
    assert (r.status, r.body) == (404, {"error": "customer not found"})


def test_lifetime_value_no_orders(shop):
    r = shop.insights.handle_lifetime_value("c1")
    assert r.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_applies_discount(shop):
    ids = [shop.orders.handle_create({"customer_id": "c2", "items": [{"sku": "LAMP", "quantity": 1}]}).body["order_id"]
           for _ in range(3)]
    shop.orders.handle_cancel(ids[0])
    expected = sum(shop.orders.handle_get(i).body["total_cents"] for i in ids[1:])
    r = shop.insights.handle_lifetime_value("c2")
    assert r.status == 200
    assert r.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": expected}
